125"><img src="http://s.ma.tt/files/2008/07/mcm_2125-195x129.jpg" width="195" height="129" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2128/" title="mcm_2128"><img src="http://s.ma.tt/files/2008/07/mcm_2128-139x210.jpg" width="139" height="210" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2131/" title="mcm_2131"><img src="http://s.ma.tt/files/2008/07/mcm_2131-139x210.jpg" width="139" height="210" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2136/" title="mcm_2136"><img src="http://s.ma.tt/files/2008/07/mcm_2136-195x129.jpg" width="195" height="129" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2139/" title="mcm_2139"><img src="http://s.ma.tt/files/2008/07/mcm_2139-139x210.jpg" width="139" height="210" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2140/" title="mcm_2140"><img src="http://s.ma.tt/files/2008/07/mcm_2140-139x210.jpg" width="139" height="210" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2141/" title="mcm_2141"><img src="http://s.ma.tt/files/2008/07/mcm_2141-139x210.jpg" width="139" height="210" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2144/" title="mcm_2144"><img src="http://s.ma.tt/files/2008/07/mcm_2144-195x129.jpg" width="195" height="129" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2149/" title="mcm_2149"><img src="http://s.ma.tt/files/2008/07/mcm_2149-139x210.jpg" width="139" height="210" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2150/" title="mcm_2150"><img src="http://s.ma.tt/files/2008/07/mcm_2150-195x129.jpg" width="195" height="129" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2152/" title="mcm_2152"><img src="http://s.ma.tt/files/2008/07/mcm_2152-195x129.jpg" width="195" height="129" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2154/" title="mcm_2154"><img src="http://s.ma.tt/files/2008/07/mcm_2154-195x129.jpg" width="195" height="129" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2156/" title="mcm_2156"><img src="http://s.ma.tt/files/2008/07/mcm_2156-195x129.jpg" width="195" height="129" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2162/" title="mcm_2162"><img src="http://s.ma.tt/files/2008/07/mcm_2162-195x129.jpg" width="195" height="129" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2163/" title="mcm_2163"><img src="http://s.ma.tt/files/2008/07/mcm_2163-195x129.jpg" width="195" height="129" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2167/" title="mcm_2167"><img src="http://s.ma.tt/files/2008/07/mcm_2167-195x129.jpg" width="195" height="129" class="attachment-thumbnail" alt="" /></a>\n<a href="http://ma.tt/2008/07/july-4th-picnic/mcm_2181/" title="mcm_2181"><img src="http://s.ma.tt/files/2008/07/mcm_2181-195x129.jpg" width="195" height="129" class="attachment-thumbnail" alt="" /></a>";}i:31;a:7:{s:5:"title";s:75:"Weblog Tools Collection: WordPress Plugin Competition: Send in your entries";s:4:"guid";s:40:"http://weblogtoolscollection.com/?p=3717";s:4:"link";s:103:"http://weblogtoolscollection.com/archives/2008/07/06/wordpress-plugin-competition-send-in-your-entries/";s:11:"description";s:930:"<p>Less than 5 days remain for the close of the WordPress Plugin Competition.</p>\n<p>Please send in your entries before the deadline to <strong>wpplugincomp [at] wltc [dot] net</strong> with the subject line as &#8220;<strong>WP Plugin Competition:</strong> <em>Plugin Name</em>&#8220;.</p>\n<p>Have you signed up at the <a href="http://weblogtoolscollection.com/pluginblog/">Plugin Competition Blog</a>?</p>\n<p>If you haven&#8217;t yet done so then please signup there and send an email to the same address above with the subject line &#8220;<strong>Author Permission:</strong> <em>Username</em>&#8221; and we will give you the necessary access to make the post.</p>\n<p>There is over <a href="http://weblogtoolscollection.com/plugin-competition-prizes/">$3800 in prizes</a> to be won.</p>\n<p>Do you wish to sponsor a prize? Please use the <a href="http://weblogtoolscollection.com/contact-me/">contact form</a> to let us know.</p>";s:7:"pubdate";s:31:"Sun, 06 Jul 2008 13:57:57 +0000";s:2:"dc";a:1:{s:7:"creator";s:4:"Ajay";}s:7:"summary";s:930:"<p>Less than 5 days remain for the close of the WordPress Plugin Competition.</p>\n<p>Please send in your entries before the deadline to <strong>wpplugincomp [at] wltc [dot] net</strong> with the subject line as &#8220;<strong>WP Plugin Competition:</strong> <em>Plugin Name</em>&#8220;.</p>\n<p>Have you signed up at the <a href="http://weblogtoolscollection.com/pluginblog/">Plugin Competition Blog</a>?</p>\n<p>If you haven&#8217;t yet done so then please signup there and send an email to the same address above with the subject line &#8220;<strong>Author Permission:</strong> <em>Username</em>&#8221; and we will give you the necessary access to make the post.</p>\n<p>There is over <a href="http://weblogtoolscollection.com/plugin-competition-prizes/">$3800 in prizes</a> to be won.</p>\n<p>Do you wish to sponsor a prize? Please use the <a href="http://weblogtoolscollection.com/contact-me/">contact form</a> to let us know.</p>";}i:32;a:7:{s:5:"title";s:60:"Weblog Tools Collection: WordPress Plugin Releases for 07/05";s:4:"guid";s:40:"http://weblogtoolscollection.com/?p=3714";s:4:"link";s:88:"http://weblogtoolscollection.com/archives/2008/07/05/wordpress-plugin-releases-for-0705/";s:11:"description";s:1866:"<p><a href="http://www.deepsarcasm.com/dev/stumbleupon-favorites/"><strong>StumbleUpon Favorites</strong></a></p>\n<p>StumbleUpon Favorites is a widget based on the default RSS widget that was developed to allow the sharing of bookmarks with blog visitors. This plugin makes it much easier to use and customize the list grabbed from your own <a href="http://www.stumbleupon.com">StumbleUpon</a> account.</p>\n<p><a href="http://www.tiafo.com/plugins/2008/06/14/pics-wordpress-plugin/"><strong>Automated Picture Posting Plugin</strong></a></p>\n<p>PICS (Picture Increment Cron System) is a WordPress Plugin designed to allow you to automatically post pictures to your WordPress blog at a administrator determined timed interval.</p>\n<p><a href="http://www.prelovac.com/vladimir/wordpress-plugins/wp-wall"><strong>WP Wall</strong></a></p>\n<p>&#8220;Wall&#8221; widget that appears in your blog’s side bar. Readers can add a quick comment about the blog as a whole, and the comment will appear in the sidebar immediately (without reloading the page).</p>\n<p><a href="http://www.prelovac.com/vladimir/wordpress-plugins/live-blogroll"><strong>Live Blogroll</strong></a></p>\n<p>This plugin shows a number of ‘recent posts’ for each link in your Blogroll using Ajax. When the user hover above the link the rss feed from the site is automatically detected and a number of recent posts is shown dynamically in a box.</p>\n<p><a href="http://wangenweb.com/wordpreciousss/"><strong>WordPreciousss</strong></a></p>\n<p>WordPreciousss extends the theme functionality in WordPress and actually creates a theme framework on your site - having a global set of templates, so all themes can basicly be CSS only if you like. WordPreciousss also gives you the opportunity to add template files to Child Themes, so you&#8217;re not limited to using only style.css and functions.php.</p>";s:7:"pubdate";s:31:"Sat, 05 Jul 2008 11:13:21 +0000";s:2:"dc";a:1:{s:7:"creator";s:4:"Ajay";}s:7:"summary";s:1866:"<p><a href="http://www.deepsarcasm.com/dev/stumbleupon-favorites/"><strong>StumbleUpon Favorites</strong></a></p>\n<p>StumbleUpon Favorites is a widget based on the default RSS widget that was developed to allow the sharing of bookmarks with blog visitors. This plugin makes it much easier to use and customize the list grabbed from your own <a href="http://www.stumbleupon.com">StumbleUpon</a> account.</p>\n<p><a href="http://www.tiafo.com/plugins/2008/06/14/pics-wordpress-plugin/"><strong>Automated Picture Posting Plugin</strong></a></p>\n<p>PICS (Picture Increment Cron System) is a WordPress Plugin designed to allow you to automatically post pictures to your WordPress blog at a administrator determined timed interval.</p>\n<p><a href="http://www.prelovac.com/vladimir/wordpress-plugins/wp-wall"><strong>WP Wall</strong></a></p>\n<p>&#8220;Wall&#8221; widget that appears in your blog’s side bar. Readers can add a quick comment about the blog as a whole, and the comment will appear in the sidebar immediately (without reloading the page).</p>\n<p><a href="http://www.prelovac.com/vladimir/wordpress-plugins/live-blogroll"><strong>Live Blogroll</strong></a></p>\n<p>This plugin shows a number of ‘recent posts’ for each link in your Blogroll using Ajax. When the user hover above the link the rss feed from the site is automatically detected and a number of recent posts is shown dynamically in a box.</p>\n<p><a href="http://wangenweb.com/wordpreciousss/"><strong>WordPreciousss</strong></a></p>\n<p>WordPreciousss extends the theme functionality in WordPress and actually creates a theme framework on your site - having a global set of templates, so all themes can basicly be CSS only if you like. WordPreciousss also gives you the opportunity to add template files to Child Themes, so you&#8217;re not limited to using only style.css and functions.php.</p>";}i:33;a:7:{s:5:"title";s:23:"Matt: IE6 Independence?";s:4:"guid";s:20:"http://ma.tt/?p=6566";s:4:"link";s:38:"http://ma.tt/2008/07/ie6-independence/";s:11:"description";s:2019:"<p>Hot off the news <a href="http://37signals.blogs.com/products/2008/07/basecamp-phasin.html">that 37signals is removing support for IE6 in their products</a> I thought it would be interesting to look at the stats from WordPress.com as an update to <a href="http://ma.tt/2007/08/browser-stats/">my previous post just under a year ago</a>. Is it reasonable to drop support for IE6 in a mainstream app?</p>\n<p>These stats cover Jan 1 - Jun 30: 787 million &#8220;absolute unique&#8221; visitors, 1.6 billion visits, and 3.3 billion pageviews. I feel these numbers are large enough and WordPress.com-hosted blogs diverse enough to be fairly representative. All the numbers come from Google Analytics. In parentheses I&#8217;ve put the delta from the last time I blogged these stats.</p>\n<ol>\n<li>59.41% - Internet Explorer (down 3.05%), sub-breakdown:\n<ol>\n<li>53.42% - Version 7.0 (up 18.25%)</li>\n<li>46.28% - Version 6.0 (down 17.82%)</li>\n<li>0.14% - Version 5.5 (down 0.14%)</li>\n</ol>\n</li>\n<li>32.82% - Firefox (up 2.08%)</li>\n<li>4.81% - Safari (up 0.98%)</li>\n<li>2.04% - Opera (up 0.26%)</li>\n<li>0.41% - Mozilla (down 0.11%)</li>\n</ol>\n<p>The operating system breakdown:</p>\n<ol>\n<li>89.41% - Windows (down 0.95%)</li>\n<li>7.86% - Macintosh (up 1.13%)</li>\n<li>1.82% - Linux (down 0.37%)</li>\n<li>0.17% - iPhone (out of nowhere!)</li>\n<li>0.10% - PlayStation Portable (up 0.07%)</li>\n</ol>\n<p>So as you can see, IE6 users account for about 27% of all the visits we saw. If I were building something for &#8220;the internet&#8221; IE6 compatibility would still very much be on my radar. Everyone&#8217;s users or customers are different, and if I saw IE6 falling below 10% on one of my sites I&#8217;d probably very seriously consider what 37signals is doing.</p>\n<p>The good news is most trends are going in the right direction: strong growth of Firefox, IE7, and Macintosh, and the iPhone came out of nowhere to generate 2.6 million visits (and another 1.1 million from the iTouch).</p>\n<p>Happy July 4th!</p>";s:7:"pubdate";s:31:"Fri, 04 Jul 2008 19:23:46 +0000";s:2:"dc";a:1:{s:7:"creator";s:4:"Matt";}s:7:"summary";s:2019:"<p>Hot off the news <a href="http://37signals.blogs.com/products/2008/07/basecamp-phasin.html">that 37signals is removing support for IE6 in their products</a> I thought it would be interesting to look at the stats from WordPress.com as an update to <a href="http://ma.tt/2007/08/browser-stats/">my previous post just under a year ago</a>. Is it reasonable to drop support for IE6 in a mainstream app?</p>\n<p>These stats cover Jan 1 - Jun 30: 787 million &#8220;absolute unique&#8221; visitors, 1.6 billion visits, and 3.3 billion pageviews. I feel these numbers are large enough and WordPress.com-hosted blogs diverse enough to be fairly representative. All the numbers come from Google Analytics. In parentheses I&#8217;ve put the delta from the last time I blogged these stats.</p>\n<ol>\n<li>59.41% - Internet Explorer (down 3.05%), sub-breakdown:\n<ol>\n<li>53.42% - Version 7.0 (up 18.25%)</li>\n<li>46.28% - Version 6.0 (down 17.82%)</li>\n<li>0.14% - Version 5.5 (down 0.14%)</li>\n</ol>\n</li>\n<li>32.82% - Firefox (up 2.08%)</li>\n<li>4.81% - Safari (up 0.98%)</li>\n<li>2.04% - Opera (up 0.26%)</li>\n<li>0.41% - Mozilla (down 0.11%)</li>\n</ol>\n<p>The operating system breakdown:</p>\n<ol>\n<li>89.41% - Windows (down 0.95%)</li>\n<li>7.86% - Macintosh (up 1.13%)</li>\n<li>1.82% - Linux (down 0.37%)</li>\n<li>0.17% - iPhone (out of nowhere!)</li>\n<li>0.10% - PlayStation Portable (up 0.07%)</li>\n</ol>\n<p>So as you can see, IE6 users account for about 27% of all the visits we saw. If I were building something for &#8220;the internet&#8221; IE6 compatibility would still very much be on my radar. Everyone&#8217;s users or customers are different, and if I saw IE6 falling below 10% on one of my sites I&#8217;d probably very seriously consider what 37signals is doing.</p>\n<p>The good news is most trends are going in the right direction: strong growth of Firefox, IE7, and Macintosh, and the iPhone came out of nowhere to generate 2.6 million visits (and another 1.1 million from the iTouch).</p>\n<p>Happy July 4th!</p>";}i:34;a:7:{s:5:"title";s:59:"Weblog Tools Collection: WordPress Theme Releases for 07/04";s:4:"guid";s:40:"http://weblogtoolscollection.com/?p=3707";s:4:"link";s:87:"http://weblogtoolscollection.com/archives/2008/07/04/wordpress-theme-releases-for-0704/";s:11:"description";s:2880:"<h3>Two Column Themes</h3>\n<p><a href="http://themeshaper.com/thematic-for-wordpress/"><strong>Thematic</strong></a></p>\n<p><a href="http://themeshaper.com/thematic/"><img src="http://weblogtoolscollection.com/b2-img/2008/07/thematic-screenshot-150x150.jpg" alt="Thematic Demo" title="Thematic Demo" width="150" height="150" /></a></p>\n<p>Thematic is a two column WordPress development theme with widgetized areas above and below the content, Options for Multi-Author blogs and many other features.</p>\n<p><a href="http://www.blogchemistry.com/2008/07/03/free-wordpress-theme-portofino/"><strong>Portofino</strong></a></p>\n<p><a href="http://demo.blogchemistry.com/?wptheme=portofino"><img src="http://weblogtoolscollection.com/b2-img/2008/07/portofino-150x150.jpg" alt="Portofino" title="Portofino" class="alignnone size-thumbnail wp-image-3711" width="150" height="150" /></a></p>\n<p>Portofino is a postcard from the Italian Riviera - once fishing village, now resort of the rich and powerful who wouldn’t be seen dead in Monte Carlo next door. Portofino is also a 2 column fixed-width WordPress theme, with righthand sidebar, enabled for widgets.</p>\n<p><a href="http://www.webminimalist.com/minimalist-vintage-wordpress-theme.htm"><strong>Minimalist Vintage</strong></a></p>\n<p><a href="http://demo.webminimalist.com/index.php?wptheme=Minimalist+Vintage"><img src="http://weblogtoolscollection.com/b2-img/2008/07/minimalist-vintage-blog-150x150.jpg" alt="Minimalist Vintage" title="Minimalist Vintage" class="alignnone size-thumbnail wp-image-3712" width="150" height="150" /></a></p>\n<p>Minimalist Vintage Wordpress Theme, was created based on original theme for WebMinimalist.com. You can choose to make a site with Static Page on the home page or make regular blog as your home page.</p>\n<h3>Three Column Themes</h3>\n<p><strong>Atari Command</strong></p>\n<p><img src="http://weblogtoolscollection.com/b2-img/2008/07/ataricommand_screen-150x150.jpg" title="Atari Command" class="alignnone size-thumbnail wp-image-3710" width="150" height="150" /></p>\n<p>Atari Command is a three column theme based on the arcade console. It has place for 155px images in the sidebar. <em>EDIT: Link removed due to copyright complaints</em></p>\n<p><strong><a href="http://www.kabatology.com/07/04/ndomche-summary-theme-%E2%80%93-iii-column-version-released/">Ndomche Summary Theme</a></strong></p>\n<p><a href="http://www.kabatology.com/demo/ndomche/"><img src="http://weblogtoolscollection.com/b2-img/2008/07/ndomcheiii_screenshot-150x150.png" alt="Ndomche" title="Ndomche" class="alignnone size-thumbnail wp-image-3713" width="150" height="150" /></a></p>\n<p>A clean three column version of the Ndomche Summary theme. It has 4 sidebars - the single post has customizable sidebar of its own where you can place various widgets and so on. This theme includes no images &#8212; ads apart.</p>";s:7:"pubdate";s:31:"Fri, 04 Jul 2008 18:43:20 +0000";s:2:"dc";a:1:{s:7:"creator";s:4:"Ajay";}s:7:"summary";s:2880:"<h3>Two Column Themes</h3>\n<p><a href="http://themeshaper.com/thematic-for-wordpress/"><strong>Thematic</strong></a></p>\n<p><a href="http://themeshaper.com/thematic/"><img src="http://weblogtoolscollection.com/b2-img/2008/07/thematic-screenshot-150x150.jpg" alt="Thematic Demo" title="Thematic Demo" width="150" height="150" /></a></p>\n<p>Thematic is a two column WordPress development theme with widgetized areas above and below the content, Options for Multi-Author blogs and many other features.</p>\n<p><a href="http://www.blogchemistry.com/2008/07/03/free-wordpress-theme-portofino/"><strong>Portofino</strong></a></p>\n<p><a href="http://demo.blogchemistry.com/?wptheme=portofino"><img src="http://weblogtoolscollection.com/b2-img/2008/07/portofino-150x150.jpg" alt="Portofino" title="Portofino" class="alignnone size-thumbnail wp-image-3711" width="150" height="150" /></a></p>\n<p>Portofino is a postcard from the Italian Riviera - once fishing village, now resort of the rich and powerful who wouldn’t be seen dead in Monte Carlo next door. Portofino is also a 2 column fixed-width WordPress theme, with righthand sidebar, enabled for widgets.</p>\n<p><a href="http://www.webminimalist.com/minimalist-vintage-wordpress-theme.htm"><strong>Minimalist Vintage</strong></a></p>\n<p><a href="http://demo.webminimalist.com/index.php?wptheme=Minimalist+Vintage"><img src="http://weblogtoolscollection.com/b2-img/2008/07/minimalist-vintage-blog-150x150.jpg" alt="Minimalist Vintage" title="Minimalist Vintage" class="alignnone size-thumbnail wp-image-3712" width="150" height="150" /></a></p>\n<p>Minimalist Vintage Wordpress Theme, was created based on original theme for WebMinimalist.com. You can choose to make a site with Static Page on the home page or make regular blog as your home page.</p>\n<h3>Three Column Themes</h3>\n<p><strong>Atari Command</strong></p>\n<p><img src="http://weblogtoolscollection.com/b2-img/2008/07/ataricommand_screen-150x150.jpg" title="Atari Command" class="alignnone size-thumbnail wp-image-3710" width="150" height="150" /></p>\n<p>Atari Command is a three column theme based on the arcade console. It has place for 155px images in the sidebar. <em>EDIT: Link removed due to copyright complaints</em></p>\n<p><strong><a href="http://www.kabatology.com/07/04/ndomche-summary-theme-%E2%80%93-iii-column-version-released/">Ndomche Summary Theme</a></strong></p>\n<p><a href="http://www.kabatology.com/demo/ndomche/"><img src="http://weblogtoolscollection.com/b2-img/2008/07/ndomcheiii_screenshot-150x150.png" alt="Ndomche" title="Ndomche" class="alignnone size-thumbnail wp-image-3713" width="150" height="150" /></a></p>\n<p>A clean three column version of the Ndomche Summary theme. It has 4 sidebars - the single post has customizable sidebar of its own where you can place various widgets and so on. This theme includes no images &#8212; ads apart.</p>";}i:35;a:7:{s:5:"title";s:44:"Weblog Tools Collection: Parent Child Themes";s:4:"guid";s:40:"http://weblogtoolscollection.com/?p=3706";s:4:"link";s:73:"http://weblogtoolscollection.com/archives/2008/07/03/parent-child-themes/";s:11:"description";s:681:"<p>I didn&#8217;t know these existed, but apparently you can assign a child theme to a parent theme. A child theme inherits all the template files of the parent theme except for the style.css file and functions.php, which take precedence over the original. Ian Stewart of Themeshaper.com published a post ( <a href="http://themeshaper.com/functions-php-wordpress-child-themes/" target="_blank">Functions.php WordPress Child Themes</a> ) which goes into detail on how to redesign your blog the smart way basing the work off of a theme framework.</p>\n<p>I&#8217;m still not sure about the usage of parent-child themes so any help you guys/gals could give me would be appreciated.</p>";s:7:"pubdate";s:31:"Fri, 04 Jul 2008 01:46:33 +0000";s:2:"dc";a:1:{s:7:"creator";s:13:"Jeff Chandler";}s:7:"summary";s:681:"<p>I didn&#8217;t know these existed, but apparently you can assign a child theme to a parent theme. A child theme inherits all the template files of the parent theme except for the style.css file and functions.php, which take precedence over the original. Ian Stewart of Themeshaper.com published a post ( <a href="http://themeshaper.com/functions-php-wordpress-child-themes/" target="_blank">Functions.php WordPress Child Themes</a> ) which goes into detail on how to redesign your blog the smart way basing the work off of a theme framework.</p>\n<p>I&#8217;m still not sure about the usage of parent-child themes so any help you guys/gals could give me would be appreciated.</p>";}i:36;a:7:{s:5:"title";s:56:"Donncha: More ways to stop spammers and unwanted traffic";s:4:"guid";s:29:"http://ocaoimh.ie/?p=89493794";s:4:"link";s:77:"http://ocaoimh.ie/2008/07/03/more-ways-to-stop-spammers-and-unwanted-traffic/";s:11:"description";s:8622:"<p><strong>Comment spammers</strong>, trackback spam, stupid bots and AVG linkscanner eating into your bandwidth and server resources? Here&#8217;s how to put a dent in their activities with a few mod_rewrite rules.</p>\n<p>I hate those blogs that send me fake trackbacks and pingbacks. Unfortunately it&#8217;s impossible to stop but this morning I figured out a way of stopping some of them.</p>\n<p>Look through the log files of your web server for the string &#8216; &#8220;-&#8221; &#8220;-&#8221;&#8216;. Lots of requests there aren&#8217;t there? I found 914 requests yesterday. Those are requests without a USER_AGENT or HTTP_REFERER and almost all of them are suspicious because they weren&#8217;t followed by requests for images, stylesheets. or Javascript files. Unfortunately the WordPress cron server also falls into this category so you need to filter out requests from your own server&#8217;s IP address.</p>\n<p>This morning I checked up on a spam trackback that came in. This one came from 85.177.33.196:<br />\n<blockquote>URL: /xmlrpc.php<br />\nHTTP_RAW_POST_DATA: &lt;?xml version=&#8221;1.0&#8243;?><br />\n&lt;methodCall><br />\n&lt;methodName>pingback.ping&lt;/methodName><br />\n&lt;params><br />\n&lt;param><br />\n&lt;value>&lt;string>http://7wins.&nbsp;eu/cbprod/detail_10347/cure+your+tight+foreskin.html&lt;/string>&lt;/value><br />\n&lt;/param><br />\n&lt;param><br />\n&lt;value>&lt;string>http://ocaoimh.ie/2005/03/01/i-am-bored-sites-for-when-youre-bored/all-comments/&lt;/string>&lt;/value><br />\n&lt;/param><br />\n&lt;/params><br />\n&lt;/methodCall></p></blockquote>\n<p>I looked through my log files for that IP address and discovered the following:<br />\n<blockquote>85.177.33.196 - - [03/Jul/2008:06:40:01 +0000] &#8220;GET /2005/02/18/10-more-ways-to-make-money-with-your-digital-cameras/ HTTP/1.0&#8243; 200 36151 &#8220;-&#8221; &#8220;-&#8221;<br />\n85.177.33.196 - - [03/Jul/2008:07:04:18 +0000] &#8220;GET /2007/06/07/im-not-the-only-one-to-love-the-alfa-147/ HTTP/1.0&#8243; 200 44967 &#8220;-&#8221; &#8220;-&#8221;<br />\n85.177.33.196 - - [03/Jul/2008:08:09:40 +0000] &#8220;GET /2005/03/01/i-am-bored-sites-for-when-youre-bored/all-comments/ HTTP/1.0&#8243; 200 410423 &#8220;-&#8221; &#8220;-&#8221;<br />\n85.177.33.196 - - [03/Jul/2008:08:09:44 +0000] &#8220;POST /xmlrpc.php HTTP/1.0&#8243; 200 249 &#8220;-&#8221; &#8220;XML-RPC for PHP 2.2.1&#8243;<br />\n85.177.33.196 - - [03/Jul/2008:09:00:09 +0000] &#8220;GET /2007/10/28/what-time-is-it-wordpress/ HTTP/1.0&#8243; 200 63332 &#8220;-&#8221; &#8220;-&#8221;</p></blockquote>\n<p>So, the spammer grabs &#8220;/2005/03/01/i-am-bored-sites-for-when-youre-bored/all-comments/&#8221; at 8:09am and 4 seconds later sends a trackback spam to the same blog post. Annoying isn&#8217;t it?</p>\n<p>The following mod_rewrite rules will kill those fake GET requests dead.<br />\n<blockquote># stop requests with no UA or referrer<br />\nRewriteCond %{HTTP_REFERER} ^$<br />\nRewritecond %{HTTP_USER_AGENT} ^$<br />\nRewriteCond %{REMOTE_ADDR} !^64\\.22\\.71\\.36$<br />\nRewriteRule ^(.*) - [F]</p></blockquote>\n<p>Replace &#8220;64\\.22\\.71\\.36&#8243; with the IP address of your own server. If you don&#8217;t know what it is, look through your logs for requests for wp-cron.php, run <code>ifconfig</code> from the command line, or check with your hosting company.<br />\nHere are a few of the requests already stopped this morning:<br />\n<blockquote>72.21.40.122 - - [03/Jul/2008:09:59:59 +0000] &#8220;GET /2005/04/02/photo-matt-a-response-to-the-noise/ HTTP/1.1&#8243; 403 248 &#8220;-&#8221; &#8220;-&#8221;<br />\n216.32.81.66 - - [03/Jul/2008:10:00:11 +0000] &#8220;GET /2006/12/14/bupa-to-leave-irish-market/ HTTP/1.1&#8243; 403 240 &#8220;-&#8221; &#8220;-&#8221;<br />\n66.228.208.166 - - [03/Jul/2008:10:03:18 +0000] &#8220;GET /2008/05/23/youre-looking-so-silly-wii-fit HTTP/1.1&#8243; 403 212 &#8220;-&#8221; &#8220;-&#8221;<br />\n216.32.81.74 - - [03/Jul/2008:10:04:52 +0000] &#8220;GET /1998/03/22/for-the-next-month-o/ HTTP/1.1&#8243; 403 234 &#8220;-&#8221; &#8220;-&#8221;<br />\n69.46.20.87 - - [03/Jul/2008:10:06:06 +0000] &#8220;GET /2006/10/01/killing-off-php/ HTTP/1.1&#8243; 403 229 &#8220;-&#8221; &#8220;-&#8221;<br />\n72.21.58.74 - - [03/Jul/2008:10:07:54 +0000] &#8220;GET /2005/08/12/thunderbird-feeds-and-messages-duplicates/ HTTP/1.1&#8243; 403 255 &#8220;-&#8221; &#8220;-&#8221;</p></blockquote>\n<p>Some spam bots are stupid. They don&#8217;t know where your wp-comments-post.php is. That&#8217;s the file your comment form feeds when a comment is made. If your blog is installed in the root, &#8220;/&#8221;, of your domain you can add this one line to stop the 404 requests generated:<br />\n<blockquote>RewriteRule ^(.*)/wp-comments-post.php - [F,L]</p></blockquote>\n<p>Trackbacks and pingbacks almost always come from sane looking user agents. They usually have the blog or forum software name to identify them. Look for &#8220;/trackback/&#8221; POSTs in your logs. Notice how 99% of them have browser names in them? Here&#8217;s how to stop them, and this has been <a href="http://www.tomrafteryit.net/blocking-trackback-spam-using-htaccess/">documented</a> for a <em>long</em> time:<br />\n<blockquote>RewriteCond %{HTTP_USER_AGENT} ^.*(Opera|Mozilla|MSIE).*$ [OR]<br />\nRewriteCond %{HTTP_USER_AGENT} ^$<br />\nRewriteCond %{REQUEST_METHOD} ^POST$<br />\nRewriteRule ^(.*)/trackback/ - [F,L]</p></blockquote>\n<p>I&#8217;ve been using that chunk of code for ages. It works exceptionally well. This was prompted by a deluge of 40,000 spam trackbacks this site received in one day a few months ago. </p>\n<p>If you use my <a href="http://ocaoimh.ie/cookies-for-comments/">Cookies for Comments</a> plugin. Check your browser for the cookie it leaves and use the following code to block almost all of your comment spam:<br />\n<blockquote>RewriteCond %{HTTP_COOKIE} !^.*put_cookie_value_here.*$<br />\nRewriteRule ^wp-comments-post.php - [F,L]</p></blockquote>\n<p>That will block the spammers even before they hit any PHP script. Your server will breeze through the worst spam attempts. It blocked 2308 comment spam attempts yesterday. Unfortunately it also stops the occasional human visitor leaving a comment but I think it&#8217;s worth it.</p>\n<p><em>Do something different. That&#8217;s what you have to do. Place a hurdle before the spammers and they&#8217;ll fall. On that note, I shouldn&#8217;t really be blogging all this, but almost all these ideas can be found elsewhere already and the spammers still haven&#8217;t adapted.</em></p>\n<p><strong>Unwanted traffic?</strong> What&#8217;s that? Surely all visitors are good? Nope, unfortunately not. Robert <a href="http://blog.sweetnam.eu/2008/06/28/avg-antivirus-sending-me-lots-of-unwanted-traffic-and-how-i-dealt-with-it/">alerted me</a> to the fact that AVG anti-virus now includes an AJAX powered browser plugin called &#8220;Linkscanner&#8221; that scans all the links on search engine result pages for viruses and malicious code. Unfortunately that generates a huge number of requests for pages that are never even seen by the visitor. I counted over 7,000 hits yesterday.</p>\n<p>Thankfully Padraig Brady <a href="http://www.pixelbeat.org/docs/web/avg_linkscanner.html">has a solution</a>. I hope he doesn&#8217;t mind if I reprint his mod_rewrite rules here (unfortunately WordPress changes the &#8221; character so you&#8217;ll have to change them back, or grab the code from Padraig&#8217;s page.)</p>\n<blockquote><p>#Here we assume certain MSIE 6.0 agents are from linkscanner<br />\n#redirect these requests back to avg in the hope they&#8217;ll see their silliness<br />\nRewritecond %{HTTP_USER_AGENT} &#8220;.*MSIE 6.0; Windows NT 5.1; SV1.$&#8221; [OR]<br />\nRewritecond %{HTTP_USER_AGENT} &#8220;.*MSIE 6.0; Windows NT 5.1;1813.$&#8221;<br />\nRewriteCond %{HTTP_REFERER} ^$<br />\nRewriteCond %{HTTP:Accept-Encoding} ^$<br />\nRewriteRule ^.* http://www.avg.com/?LinkScannerSucks [R=307,L]</p></blockquote>\n<p><img src="http://ocaoimh.ie/?voyeur=1" /></p><p><strong>Related Posts</strong><ul><li><a href="http://ocaoimh.ie/2008/03/06/please-sir-can-i-have-more/" rel="bookmark" title="Permanent Link: Please sir, can I have more?">Please sir, can I have more?</a></li><li><a href="http://ocaoimh.ie/2002/11/25/kernel-traffic-192/" rel="bookmark" title="Permanent Link: Kernel Traffic #192 For 18 Nov &#8230;">Kernel Traffic #192 For 18 Nov &#8230;</a></li><li><a href="http://ocaoimh.ie/2002/12/11/learning-by-shipping/" rel="bookmark" title="Permanent Link: Learning by Shipping - this re &#8230;">Learning by Shipping - this re &#8230;</a></li></ul></p>";s:7:"pubdate";s:31:"Thu, 03 Jul 2008 11:18:45 +0000";s:2:"dc";a:1:{s:7:"creator";s:7:"Donncha";}s:7:"summary";s:8622:"<p><strong>Comment spammers</strong>, trackback spam, stupid bots and AVG linkscanner eating into your bandwidth and server resources? Here&#8217;s how to put a dent in their activities with a few mod_rewrite rules.</p>\n<p>I hate those blogs that send me fake trackbacks and pingbacks. Unfortunately it&#8217;s impossible to stop but this morning I figured out a way of stopping some of them.</p>\n<p>Look through the log files of your web server for the string &#8216; &#8220;-&#8221; &#8220;-&#8221;&#8216;. Lots of requests there aren&#8217;t there? I found 914 requests yesterday. Those are requests without a USER_AGENT or HTTP_REFERER and almost all of them are suspicious because they weren&#8217;t followed by requests for images, stylesheets. or Javascript files. Unfortunately the WordPress cron server also falls into this category so you need to filter out requests from your own server&#8217;s IP address.</p>\n<p>This morning I checked up on a spam trackback that came in. This one came from 85.177.33.196:<br />\n<blockquote>URL: /xmlrpc.php<br />\nHTTP_RAW_POST_DATA: &lt;?xml version=&#8221;1.0&#8243;?><br />\n&lt;methodCall><br />\n&lt;methodName>pingback.ping&lt;/methodName><br />\n&lt;params><br />\n&lt;param><br />\n&lt;value>&lt;string>http://7wins.&nbsp;eu/cbprod/detail_10347/cure+your+tight+foreskin.html&lt;/string>&lt;/value><br />\n&lt;/param><br />\n&lt;param><br />\n&lt;value>&lt;string>http://ocaoimh.ie/2005/03/01/i-am-bored-sites-for-when-youre-bored/all-comments/&lt;/string>&lt;/value><br />\n&lt;/param><br />\n&lt;/params><br />\n&lt;/methodCall></p></blockquote>\n<p>I looked through my log files for that IP address and discovered the following:<br />\n<blockquote>85.177.33.196 - - [03/Jul/2008:06:40:01 +0000] &#8220;GET /2005/02/18/10-more-ways-to-make-money-with-your-digital-cameras/ HTTP/1.0&#8243; 200 36151 &#8220;-&#8221; &#8220;-&#8221;<br />\n85.177.33.196 - - [03/Jul/2008:07:04:18 +0000] &#8220;GET /2007/06/07/im-not-the-only-one-to-love-the-alfa-147/ HTTP/1.0&#8243; 200 44967 &#8220;-&#8221; &#8220;-&#8221;<br />\n85.177.33.196 - - [03/Jul/2008:08:09:40 +0000] &#8220;GET /2005/03/01/i-am-bored-sites-for-when-youre-bored/all-comments/ HTTP/1.0&#8243; 200 410423 &#8220;-&#8221; &#8220;-&#8221;<br />\n85.177.33.196 - - [03/Jul/2008:08:09:44 +0000] &#8220;POST /xmlrpc.php HTTP/1.0&#8243; 200 249 &#8220;-&#8221; &#8220;XML-RPC for PHP 2.2.1&#8243;<br />\n85.177.33.196 - - [03/Jul/2008:09:00:09 +0000] &#8220;GET /2007/10/28/what-time-is-it-wordpress/ HTTP/1.0&#8243; 200 63332 &#8220;-&#8221; &#8220;-&#8221;</p></blockquote>\n<p>So, the spammer grabs &#8220;/2005/03/01/i-am-bored-sites-for-when-youre-bored/all-comments/&#8221; at 8:09am and 4 seconds later sends a trackback spam to the same blog post. Annoying isn&#8217;t it?</p>\n<p>The following mod_rewrite rules will kill those fake GET requests dead.<br />\n<blockquote># stop requests with no UA or referrer<br />\nRewriteCond %{HTTP_REFERER} ^$<br />\nRewritecond %{HTTP_USER_AGENT} ^$<br />\nRewriteCond %{REMOTE_ADDR} !^64\\.22\\.71\\.36$<br />\nRewriteRule ^(.*) - [F]</p></blockquote>\n<p>Replace &#8220;64\\.22\\.71\\.36&#8243; with the IP address of your own server. If you don&#8217;t know what it is, look through your logs for requests for wp-cron.php, run <code>ifconfig</code> from the command line, or check with your hosting company.<br />\nHere are a few of the requests already stopped this morning:<br />\n<blockquote>72.21.40.122 - - [03/Jul/2008:09:59:59 +0000] &#8220;GET /2005/04/02/photo-matt-a-response-to-the-noise/ HTTP/1.1&#8243; 403 248 &#8220;-&#8221; &#8220;-&#8221;<br />\n216.32.81.66 - - [03/Jul/2008:10:00:11 +0000] &#8220;GET /2006/12/14/bupa-to-leave-irish-market/ HTTP/1.1&#8243; 403 240 &#8220;-&#8221; &#8220;-&#8221;<br />\n66.228.208.166 - - [03/Jul/2008:10:03:18 +0000] &#8220;GET /2008/05/23/youre-looking-so-silly-wii-fit HTTP/1.1&#8243; 403 212 &#8220;-&#8221; &#8220;-&#8221;<br />\n216.32.81.74 - - [03/Jul/2008:10:04:52 +0000] &#8220;GET /1998/03/22/for-the-next-month-o/ HTTP/1.1&#8243; 403 234 &#8220;-&#8221; &#8220;-&#8221;<br />\n69.46.20.87 - - [03/Jul/2008:10:06:06 +0000] &#8220;GET /2006/10/01/killing-off-php/ HTTP/1.1&#8243; 403 229 &#8220;-&#8221; &#8220;-&#8221;<br />\n72.21.58.74 - - [03/Jul/2008:10:07:54 +0000] &#8220;GET /2005/08/12/thunderbird-feeds-and-messages-duplicates/ HTTP/1.1&#8243; 403 255 &#8220;-&#8221; &#8220;-&#8221;</p></blockquote>\n<p>Some spam bots are stupid. They don&#8217;t know where your wp-comments-post.php is. That&#8217;s the file your comment form feeds when a comment is made. If your blog is installed in the root, &#8220;/&#8221;, of your domain you can add this one line to stop the 404 requests generated:<br />\n<blockquote>RewriteRule ^(.*)/wp-comments-post.php - [F,L]</p></blockquote>\n<p>Trackbacks and pingbacks almost always come from sane looking user agents. They usually have the blog or forum software name to identify them. Look for &#8220;/trackback/&#8221; POSTs in your logs. Notice how 99% of them have browser names in them? Here&#8217;s how to stop them, and this has been <a href="http://www.tomrafteryit.net/blocking-trackback-spam-using-htaccess/">documented</a> for a <em>long</em> time:<br />\n<blockquote>RewriteCond %{HTTP_USER_AGENT} ^.*(Opera|Mozilla|MSIE).*$ [OR]<br />\nRewriteCond %{HTTP_USER_AGENT} ^$<br />\nRewriteCond %{REQUEST_METHOD} ^POST$<br />\nRewriteRule ^(.*)/trackback/ - [F,L]</p></blockquote>\n<p>I&#8217;ve been using that chunk of code for ages. It works exceptionally well. This was prompted by a deluge of 40,000 spam trackbacks this site received in one day a few months ago. </p>\n<p>If you use my <a href="http://ocaoimh.ie/cookies-for-comments/">Cookies for Comments</a> plugin. Check your browser for the cookie it leaves and use the following code to block almost all of your comment spam:<br />\n<blockquote>RewriteCond %{HTTP_COOKIE} !^.*put_cookie_value_here.*$<br />\nRewriteRule ^wp-comments-post.php - [F,L]</p></blockquote>\n<p>That will block the spammers even before they hit any PHP script. Your server will breeze through the worst spam attempts. It blocked 2308 comment spam attempts yesterday. Unfortunately it also stops the occasional human visitor leaving a comment but I think it&#8217;s worth it.</p>\n<p><em>Do something different. That&#8217;s what you have to do. Place a hurdle before the spammers and they&#8217;ll fall. On that note, I shouldn&#8217;t really be blogging all this, but almost all these ideas can be found elsewhere already and the spammers still haven&#8217;t adapted.</em></p>\n<p><strong>Unwanted traffic?</strong> What&#8217;s that? Surely all visitors are good? Nope, unfortunately not. Robert <a href="http://blog.sweetnam.eu/2008/06/28/avg-antivirus-sending-me-lots-of-unwanted-traffic-and-how-i-dealt-with-it/">alerted me</a> to the fact that AVG anti-virus now includes an AJAX powered browser plugin called &#8220;Linkscanner&#8221; that scans all the links on search engine result pages for viruses and malicious code. Unfortunately that generates a huge number of requests for pages that are never even seen by the visitor. I counted over 7,000 hits yesterday.</p>\n<p>Thankfully Padraig Brady <a href="http://www.pixelbeat.org/docs/web/avg_linkscanner.html">has a solution</a>. I hope he doesn&#8217;t mind if I reprint his mod_rewrite rules here (unfortunately WordPress changes the &#8221; character so you&#8217;ll have to change them back, or grab the code from Padraig&#8217;s page.)</p>\n<blockquote><p>#Here we assume certain MSIE 6.0 agents are from linkscanner<br />\n#redirect these requests back to avg in the hope they&#8217;ll see their silliness<br />\nRewritecond %{HTTP_USER_AGENT} &#8220;.*MSIE 6.0; Windows NT 5.1; SV1.$&#8221; [OR]<br />\nRewritecond %{HTTP_USER_AGENT} &#8220;.*MSIE 6.0; Windows NT 5.1;1813.$&#8221;<br />\nRewriteCond %{HTTP_REFERER} ^$<br />\nRewriteCond %{HTTP:Accept-Encoding} ^$<br />\nRewriteRule ^.* http://www.avg.com/?LinkScannerSucks [R=307,L]</p></blockquote>\n<p><img src="http://ocaoimh.ie/?voyeur=1" /></p><p><strong>Related Posts</strong><ul><li><a href="http://ocaoimh.ie/2008/03/06/please-sir-can-i-have-more/" rel="bookmark" title="Permanent Link: Please sir, can I have more?">Please sir, can I have more?</a></li><li><a href="http://ocaoimh.ie/2002/11/25/kernel-traffic-192/" rel="bookmark" title="Permanent Link: Kernel Traffic #192 For 18 Nov &#8230;">Kernel Traffic #192 For 18 Nov &#8230;</a></li><li><a href="http://ocaoimh.ie/2002/12/11/learning-by-shipping/" rel="bookmark" title="Permanent Link: Learning by Shipping - this re &#8230;">Learning by Shipping - this re &#8230;</a></li></ul></p>";}i:37;a:7:{s:5:"title";s:49:"Weblog Tools Collection: WP.com Shifts Into Turbo";s:4:"guid";s:40:"http://weblogtoolscollection.com/?p=3703";s:4:"link";s:77:"http://weblogtoolscollection.com/archives/2008/07/03/wpcom-shifts-into-turbo/";s:11:"description";s:1485:"<p>Matt and company have announced that <a href="http://en.blog.wordpress.com/2008/07/02/gears/" target="_blank">WordPress.com now officially supports</a> <a href="http://code.google.com/apis/gears/" target="_blank">Google Gears</a>.  Gears is an extension which works with the browser to enhance web based applications. It&#8217;s known for creating local database and file storage, while running javascript in the background to update that content without slowing down the browser.</p>\n<p><a href="http://weblogtoolscollection.com/b2-img/2008/07/turbo.png"><img src="http://weblogtoolscollection.com/b2-img/2008/07/turbo.png" alt="WP.COM Now Has Google Gears Support" title="WP.COM Now Has Google Gears Support" class="alignnone size-full wp-image-3704 aligncenter" width="305" height="92" /></a></p>\n<p>Gears support in WordPress.com means you will be able to store all images and other web page components of the WordPress administration panel locally which will speed up access to those files while reducing unnecessary web traffic. To enable this feature, click on the <strong>TURBO</strong> link in the WP.COM dashboard area. This will be located in the upper right portion of the screen. You will need to have the GEARS extension installed before you will be able to take advantage of this new feature.</p>\n<p>[EDIT] Rundown on <a href="http://foolswisdom.com/wordpress-gears-offline-privacy/">Fool&#8217;s Wisdom</a> of Google Gears Privacy concerned raised. Thanks Lloyd!</p>";s:7:"pubdate";s:31:"Thu, 03 Jul 2008 09:00:37 +0000";s:2:"dc";a:1:{s:7:"creator";s:13:"Jeff Chandler";}s:7:"summary";s:1485:"<p>Matt and company have announced that <a href="http://en.blog.wordpress.com/2008/07/02/gears/" target="_blank">WordPress.com now officially supports</a> <a href="http://code.google.com/apis/gears/" target="_blank">Google Gears</a>.  Gears is an extension which works with the browser to enhance web based applications. It&#8217;s known for creating local database and file storage, while running javascript in the background to update that content without slowing down the browser.</p>\n<p><a href="http://weblogtoolscollection.com/b2-img/2008/07/turbo.png"><img src="http://weblogtoolscollection.com/b2-img/2008/07/turbo.png" alt="WP.COM Now Has Google Gears Support" title="WP.COM Now Has Google Gears Support" class="alignnone size-full wp-image-3704 aligncenter" width="305" height="92" /></a></p>\n<p>Gears support in WordPress.com means you will be able to store all images and other web page components of the WordPress administration panel locally which will speed up access to those files while reducing unnecessary web traffic. To enable this feature, click on the <strong>TURBO</strong> link in the WP.COM dashboard area. This will be located in the upper right portion of the screen. You will need to have the GEARS extension installed before you will be able to take advantage of this new feature.</p>\n<p>[EDIT] Rundown on <a href="http://foolswisdom.com/wordpress-gears-offline-privacy/">Fool&#8217;s Wisdom</a> of Google Gears Privacy concerned raised. Thanks Lloyd!</p>";}i:38;a:7:{s:5:"title";s:60:"Weblog Tools Collection: WordPress Plugin Releases for 07/02";s:4:"guid";s:40:"http://weblogtoolscollection.com/?p=3701";s:4:"link";s:88:"http://weblogtoolscollection.com/archives/2008/07/02/wordpress-plugin-releases-for-0702/";s:11:"description";s:970:"<p><strong><a href="http://blog.realthemes.com/wp-easy-uploader/">WP Easy Uploader</a></strong></p>\n<p>WP Easy Uploader was created to make the life of WordPress bloggers easier by allowing an Administrator to add plugins, themes, and any type of file to WordPress directly from inside WordPress. You no longer have to load up an FTP client just to try out that latest plugin or to upload a text document for people to download.</p>\n<p><strong><a href="http://blog.realthemes.com/wp-developer-assistant/">WP Developer Assistant</a></strong></p>\n<p>WP Developer Assistant is a WordPress plugin developed by a WordPress developer for WordPress developers.</p>\n<p><strong><a href="http://xemele.cultura.gov.br/web/lead-manager/">Lead Manager</a></strong></p>\n<p>This plugin allows the management of leads in many different website areas / sections. It is possible to order the posts in a flexible and dynamic way, providing extra visibility to the website’s features.</p>";s:7:"pubdate";s:31:"Wed, 02 Jul 2008 21:30:04 +0000";s:2:"dc";a:1:{s:7:"creator";s:4:"Ajay";}s:7:"summary";s:970:"<p><strong><a href="http://blog.realthemes.com/wp-easy-uploader/">WP Easy Uploader</a></strong></p>\n<p>WP Easy Uploader was created to make the life of WordPress bloggers easier by allowing an Administrator to add plugins, themes, and any type of file to WordPress directly from inside WordPress. You no longer have to load up an FTP client just to try out that latest plugin or to upload a text document for people to download.</p>\n<p><strong><a href="http://blog.realthemes.com/wp-developer-assistant/">WP Developer Assistant</a></strong></p>\n<p>WP Developer Assistant is a WordPress plugin developed by a WordPress developer for WordPress developers.</p>\n<p><strong><a href="http://xemele.cultura.gov.br/web/lead-manager/">Lead Manager</a></strong></p>\n<p>This plugin allows the management of leads in many different website areas / sections. It is possible to order the posts in a flexible and dynamic way, providing extra visibility to the website’s features.</p>";}i:39;a:7:{s:5:"title";s:56:"Weblog Tools Collection: Plugin Coders and WordPress 2.6";s:4:"guid";s:40:"http://weblogtoolscollection.com/?p=3702";s:4:"link";s:84:"http://weblogtoolscollection.com/archives/2008/07/02/plugin-coders-and-wordpress-26/";s:11:"description";s:433:"<p><a href="http://planetozh.com/blog/2008/07/what-plugin-coders-must-know-about-wordpress-26/">What Plugin Coders Must Know About WordPress 2.6</a>: Just like it sounds, Ozh has started a post, followed by a lively comment thread, on the challenges that can be faced by plugin coders with WordPress 2.6. This might be a good time (WordPress 2.6 Beta 2 is out) to start digging into your plugins to get them to be 2.6 compatible.</p>";s:7:"pubdate";s:31:"Wed, 02 Jul 2008 13:39:28 +0000";s:2:"dc";a:1:{s:7:"creator";s:10:"Mark Ghosh";}s:7:"summary";s:433:"<p><a href="http://planetozh.com/blog/2008/07/what-plugin-coders-must-know-about-wordpress-26/">What Plugin Coders Must Know About WordPress 2.6</a>: Just like it sounds, Ozh has started a post, followed by a lively comment thread, on the challenges that can be faced by plugin coders with WordPress 2.6. This might be a good time (WordPress 2.6 Beta 2 is out) to start digging into your plugins to get them to be 2.6 compatible.</p>";}i:40;a:7:{s:5:"title";s:32:"Ryan Boren: WordPress 2.6 Beta 2";s:4:"guid";s:23:"http://boren.nu/?p=1557";s:4:"link";s:56:"http://boren.nu/archives/2008/07/01/wordpress-26-beta-2/";s:11:"description";s:734:"<p>Another week, another beta.  New in <a href="http://wordpress.org/wordpress-2.6-beta2.zip">beta 2</a>:</p>\n<ul>\n<li>Insert image and edit image fixes</li>\n<li>SSL fixes</li>\n<li>i18n fixes</li>\n<li>Lots of new inline documentation</li>\n<li>Improved tag auto-suggest</li>\n<li>TinyMCE 3.1.1 with Opera 9.5 and Safari fixes, proper align = center removal, and improved embeds support</li>\n<li><a href="http://jquery.com/blog/2008/06/27/jquery-ui-151/">jQuery UI 1.5.1</a></li>\n</ul>\n<p>See the full list of <a href="http://trac.wordpress.org/log/trunk?action=stop_on_copy&amp;rev=8225&amp;stop_rev=8179&amp;mode=stop_on_copy">changes since beta 2</a>.</p>\n<p><a href="http://wordpress.org/wordpress-2.6-beta2.zip">Get beta 2</a>.</p>";s:7:"pubdate";s:31:"Tue, 01 Jul 2008 23:11:32 +0000";s:2:"dc";a:1:{s:7:"creator";s:4:"Ryan";}s:7:"summary";s:734:"<p>Another week, another beta.  New in <a href="http://wordpress.org/wordpress-2.6-beta2.zip">beta 2</a>:</p>\n<ul>\n<li>Insert image and edit image fixes</li>\n<li>SSL fixes</li>\n<li>i18n fixes</li>\n<li>Lots of new inline documentation</li>\n<li>Improved tag auto-suggest</li>\n<li>TinyMCE 3.1.1 with Opera 9.5 and Safari fixes, proper align = center removal, and improved embeds support</li>\n<li><a href="http://jquery.com/blog/2008/06/27/jquery-ui-151/">jQuery UI 1.5.1</a></li>\n</ul>\n<p>See the full list of <a href="http://trac.wordpress.org/log/trunk?action=stop_on_copy&amp;rev=8225&amp;stop_rev=8179&amp;mode=stop_on_copy">changes since beta 2</a>.</p>\n<p><a href="http://wordpress.org/wordpress-2.6-beta2.zip">Get beta 2</a>.</p>";}i:41;a:7:{s:5:"title";s:44:"Matt: Unofficial International WordPress Day";s:4:"guid";s:119:"http://ma.tt/2008/07/wpcandy-wordpress-themes-plugins-tips-and-tricks-%e2%80%94-unofficial-international-wordpress-day/";s:4:"link";s:27:"http://ma.tt/2008/07/wp-da/";s:11:"description";s:246:"<p><a href="http://wpcandy.com/articles/unofficial-international-wordpress-day.html">Today is Unofficial International WordPress Day</a>. It&#8217;s an honor to have such a supportive community, and things like this are very much appreciated.</p>";s:7:"pubdate";s:31:"Tue, 01 Jul 2008 23:00:47 +0000";s:2:"dc";a:1:{s:7:"creator";s:4:"Matt";}s:7:"summary";s:246:"<p><a href="http://wpcandy.com/articles/unofficial-international-wordpress-day.html">Today is Unofficial International WordPress Day</a>. It&#8217;s an honor to have such a supportive community, and things like this are very much appreciated.</p>";}i:42;a:7:{s:5:"title";s:59:"Weblog Tools Collection: WordPress Theme Releases for 07/01";s:4:"guid";s:40:"http://weblogtoolscollection.com/?p=3698";s:4:"link";s:87:"http://weblogtoolscollection.com/archives/2008/07/01/wordpress-theme-releases-for-0701/";s:11:"description";s:1023:"<h3>Two Column Themes</h3>\n<p><a href="http://www.blog2life.net/wordpress-themes/word-pressd-wordpress-admin-inside-out"><strong>Word Press&#8217;d</strong></a></p>\n<p><img src="http://weblogtoolscollection.com/b2-img/2008/07/wordpressd-150x150.gif" alt="Word Press''d" title="Word Press''d" class="alignnone size-thumbnail wp-image-3699" width="150" height="150" /></p>\n<p>Word Press&#8217;d is a free two column WordPress theme based on the the WordPress Admin interface. It&#8217;s like viewing the admin screen on the outside.</p>\n<h3>One Column Themes</h3>\n<p><strong><a href="http://notepad.ithemes.com/">Notepad</a></strong></p>\n<p><img src="http://weblogtoolscollection.com/b2-img/2008/07/notepadblack-150x150.gif" title="Notepad" class="alignnone size-thumbnail wp-image-3700" width="150" height="150" /></p>\n<p>The new Notepad  Theme is a simple, clean and sharp template designed for small  business websites for personal branding that is ideal for personal coaches,  consultants and independent professionals.</p>";s:7:"pubdate";s:31:"Tue, 01 Jul 2008 19:30:05 +0000";s:2:"dc";a:1:{s:7:"creator";s:4:"Ajay";}s:7:"summary";s:1023:"<h3>Two Column Themes</h3>\n<p><a href="http://www.blog2life.net/wordpress-themes/word-pressd-wordpress-admin-inside-out"><strong>Word Press&#8217;d</strong></a></p>\n<p><img src="http://weblogtoolscollection.com/b2-img/2008/07/wordpressd-150x150.gif" alt="Word Press''d" title="Word Press''d" class="alignnone size-thumbnail wp-image-3699" width="150" height="150" /></p>\n<p>Word Press&#8217;d is a free two column WordPress theme based on the the WordPress Admin interface. It&#8217;s like viewing the admin screen on the outside.</p>\n<h3>One Column Themes</h3>\n<p><strong><a href="http://notepad.ithemes.com/">Notepad</a></strong></p>\n<p><img src="http://weblogtoolscollection.com/b2-img/2008/07/notepadblack-150x150.gif" title="Notepad" class="alignnone size-thumbnail wp-image-3700" width="150" height="150" /></p>\n<p>The new Notepad  Theme is a simple, clean and sharp template designed for small  business websites for personal branding that is ideal for personal coaches,  consultants and independent professionals.</p>";}i:43;a:7:{s:5:"title";s:66:"Weblog Tools Collection: What You Need To Know About WordPress 2.6";s:4:"guid";s:40:"http://weblogtoolscollection.com/?p=3696";s:4:"link";s:94:"http://weblogtoolscollection.com/archives/2008/06/30/what-you-need-to-know-about-wordpress-26/";s:11:"description";s:7034:"<p>WordPress 2.5 was just released a few months ago and WordPress 2.6 has been in development for some time to be released very soon. Not only does WordPress 2.6 add more zing to a platform that has already won hearts and made blogging a wonderful experience, there are few features in WordPress 2.6 that many have requested and some that caused a little controversy.</p>\n<p>Let’s get to know a few things about WordPress 2.6 that will definitely raise few eyebrows albeit a few of them in the wrong way.</p>\n<h3>Post Revisioning</h3>\n<p>I have been a Software developer for quite long now and know how important CVS or SVN is to maintaining different versions of a file. WordPress 2.6 brings the same functionality to posts where you can have different revisions for posts.</p>\n<p>In lay terms this means that no matter how many times you make changes to the post, you will never have the “Oops, I did something wrong to the post” effect since you can always go back to a older revision of the post, and, let me add you have a cool feature where you can actually differentiate between your revisions to see what changes you made. (think wiki-like post revisions)</p>\n<h3>Tumble Your Posts</h3>\n<p>The one thing I have loved about Tumblr is the simplicity and ease of access. I simply select a link or a image and tumble it to my micro blog at Tumblr without having to go through a series of steps to actually post my content.</p>\n<p>WordPress 2.6 is taking a new approach and adds in bookmarklets that will allow you to quickly post links and image ala Tumblr. (think &#8220;Press This&#8221;)</p>\n<h3>Speed Up of Admin Interface</h3>\n<p>There has never been a reason not to use the admin interface but that said with the versatility and flexibility of WordPress many people have taken advantage and built softwares that resist you from doing so.</p>\n<p>To be quite frank, I hardly use the Admin interface except for approving and replying to comments and managing plugins and themes, but in doing that, I am definitely missing so many of the features that WordPress posting interface provides me with.</p>\n<p>WordPress 2.6 makes use of Google Gears when available to speedup and cache static files that are loaded every time you visit your WordPress admin panel.</p>\n<h3>XML-RPC access now requires Admin Permission</h3>\n<p>XML-RPC for WordPress can be used by many software applications that allow you to post content to your blog without having to visit the admin panel. The most notable one I can point out to you is Windows Live Writer.</p>\n<p>With WordPress 2.6, in new installations, the access to XML-RPC will be unavailable by default. This in short means that every user will have to go and manually enable XML-RPC to allow external applications to post to your blog. Dougal wrote a post about this recently. From his <a href="http://dougal.gunters.org/blog/2008/06/30/update-on-wordpress-blog-apis">post on the APIs</a>:</p>\n<ul>\n<li>The APIs will <strong>not</strong> be automatically disabled for sites <em>upgrading</em> from older versions. Since the APIs have previously been ‘on’ by default, they will continue to function.</li>\n<li><del datetime="2008-06-30T15:55:26+00:00">For <em>new installs</em> of WordPress 2.6 and later, there will be an option presented at install-time to enable the APIs.</del> <ins datetime="2008-06-30T15:55:26+00:00">Or not. They seem to have removed that between Beta 1 and Beta 2.</ins></li>\n<li>There will be options in the <code>Write</code> settings to enable or disable <acronym title="eXtensible Markup Language"><span class="caps">XML</span></acronym>-<acronym title="Remote Procedure Call"><span class="caps">RPC</span></acronym> posting and Atom <acronym title="Application Interface"><span class="caps">API</span></acronym> posting individually.</li>\n</ul>\n<p>Though this might appear to be a problem to som, personally I do not think that it is a inconvenience. Since users who want to use external applications will be able to do so with just a minor change in the settings and for the millions others who do not require it would never even bother with it. I definitely see this as a move to allow users the flexibility to do what they want to with their blogs without forcing them.</p>\n<h3>Activate Multiple Plugins at Once and Delete Plugins in Bulk</h3>\n<p>The one thing that went over my head with the earlier revisions of WordPress was that they allowed you to deactivate all the plugins but never allowed you to activate them at once.</p>\n<p>Also deleting plugins was never a piece of cake as users had to manually login to their FTP to delete them. I did get around to writing a plugin that would allowed users to delete plugins they no longer used from the admin panel but never released it. With WordPress 2.6 both of the concerns are answered as it will not only allow you to activate bulk plugins but also provide you with the ability to delete plugins you no longer use.</p>\n<p>I would love to see a feature where they allow users to deactivate plugins and keep a history of it and then allow users to reactivate the same plugins once again. I did end up writing a plugin for myself that kept a history of the the plugins it deactivated and then activated them while skipping those that caused a problem due to a newer version of WordPress version.</p>\n<h3>Move Your Config File to a Different Directory</h3>\n<p>Your WordPress config file contains information about things that are critical to your blog including access to your WordPress database. Though there are no known security issues with having your wp-config file in your root directory, WordPress 2.6 does allow you to move it to another directory.</p>\n<h3>Other Features</h3>\n<p>There are several other features to grab your attention and the few I talked about does not end the features you will get in the next major revision, here are some of the other things you should know about too;</p>\n<ul>\n<li>You can move your content directory from wp-content to any other place you want it to be. (This definitely will mean there are shorter links to your downloadable content or images)</li>\n<li>Better Theme Previewing.</li>\n<li>External JavaScript upgrades to TinyMCE, jQuery and jQuery UI.</li>\n<li>Customizable default avatars.</li>\n</ul>\n<p>Well hopefully this should be the best ever version yet of WordPress, though I still look forward to getting more. Let me know your views and opinions about the latest and probably greatest version of WordPress.</p>\n<p><em>Afterthought</em>: Aaron Brazell over at <a href="http://technosailor.com/2008/06/30/10-things-you-need-to-know-about-wordpress-26/">Technosailor goes into greater details on some of items on the WordPress 2.6 list of changes and updates</a>, including</p>\n<ul>\n<li>Shift Click selection of multiple checkboxes in the wp-admin</li>\n<li>More avatar options</li>\n<li>Page Templates of XML-RPC</li>\n<li>More &#8220;Press This&#8221; features</li>\n<li>Integrated Theme Preview</li>\n<li>Many other illustrated examples</li>\n</ul>";s:7:"pubdate";s:31:"Tue, 01 Jul 2008 13:45:05 +0000";s:2:"dc";a:1:{s:7:"creator";s:12:"Keith Dsouza";}s:7:"summary";s:7034:"<p>WordPress 2.5 was just released a few months ago and WordPress 2.6 has been in development for some time to be released very soon. Not only does WordPress 2.6 add more zing to a platform that has already won hearts and made blogging a wonderful experience, there are few features in WordPress 2.6 that many have requested and some that caused a little controversy.</p>\n<p>Let’s get to know a few things about WordPress 2.6 that will definitely raise few eyebrows albeit a few of them in the wrong way.</p>\n<h3>Post Revisioning</h3>\n<p>I have been a Software developer for quite long now and know how important CVS or SVN is to maintaining different versions of a file. WordPress 2.6 brings the same functionality to posts where you can have different revisions for posts.</p>\n<p>In lay terms this means that no matter how many times you make changes to the post, you will never have the “Oops, I did something wrong to the post” effect since you can always go back to a older revision of the post, and, let me add you have a cool feature where you can actually differentiate between your revisions to see what changes you made. (think wiki-like post revisions)</p>\n<h3>Tumble Your Posts</h3>\n<p>The one thing I have loved about Tumblr is the simplicity and ease of access. I simply select a link or a image and tumble it to my micro blog at Tumblr without having to go through a series of steps to actually post my content.</p>\n<p>WordPress 2.6 is taking a new approach and adds in bookmarklets that will allow you to quickly post links and image ala Tumblr. (think &#8220;Press This&#8221;)</p>\n<h3>Speed Up of Admin Interface</h3>\n<p>There has never been a reason not to use the admin interface but that said with the versatility and flexibility of WordPress many people have taken advantage and built softwares that resist you from doing so.</p>\n<p>To be quite frank, I hardly use the Admin interface except for approving and replying to comments and managing plugins and themes, but in doing that, I am definitely missing so many of the features that WordPress posting interface provides me with.</p>\n<p>WordPress 2.6 makes use of Google Gears when available to speedup and cache static files that are loaded every time you visit your WordPress admin panel.</p>\n<h3>XML-RPC access now requires Admin Permission</h3>\n<p>XML-RPC for WordPress can be used by many software applications that allow you to post content to your blog without having to visit the admin panel. The most notable one I can point out to you is Windows Live Writer.</p>\n<p>With WordPress 2.6, in new installations, the access to XML-RPC will be unavailable by default. This in short means that every user will have to go and manually enable XML-RPC to allow external applications to post to your blog. Dougal wrote a post about this recently. From his <a href="http://dougal.gunters.org/blog/2008/06/30/update-on-wordpress-blog-apis">post on the APIs</a>:</p>\n<ul>\n<li>The APIs will <strong>not</strong> be automatically disabled for sites <em>upgrading</em> from older versions. Since the APIs have previously been ‘on’ by default, they will continue to function.</li>\n<li><del datetime="2008-06-30T15:55:26+00:00">For <em>new installs</em> of WordPress 2.6 and later, there will be an option presented at install-time to enable the APIs.</del> <ins datetime="2008-06-30T15:55:26+00:00">Or not. They seem to have removed that between Beta 1 and Beta 2.</ins></li>\n<li>There will be options in the <code>Write</code> settings to enable or disable <acronym title="eXtensible Markup Language"><span class="caps">XML</span></acronym>-<acronym title="Remote Procedure Call"><span class="caps">RPC</span></acronym> posting and Atom <acronym title="Application Interface"><span class="caps">API</span></acronym> posting individually.</li>\n</ul>\n<p>Though this might appear to be a problem to som, personally I do not think that it is a inconvenience. Since users who want to use external applications will be able to do so with just a minor change in the settings and for the millions others who do not require it would never even bother with it. I definitely see this as a move to allow users the flexibility to do what they want to with their blogs without forcing them.</p>\n<h3>Activate Multiple Plugins at Once and Delete Plugins in Bulk</h3>\n<p>The one thing that went over my head with the earlier revisions of WordPress was that they allowed you to deactivate all the plugins but never allowed you to activate them at once.</p>\n<p>Also deleting plugins was never a piece of cake as users had to manually login to their FTP to delete them. I did get around to writing a plugin that would allowed users to delete plugins they no longer used from the admin panel but never released it. With WordPress 2.6 both of the concerns are answered as it will not only allow you to activate bulk plugins but also provide you with the ability to delete plugins you no longer use.</p>\n<p>I would love to see a feature where they allow users to deactivate plugins and keep a history of it and then allow users to reactivate the same plugins once again. I did end up writing a plugin for myself that kept a history of the the plugins it deactivated and then activated them while skipping those that caused a problem due to a newer version of WordPress version.</p>\n<h3>Move Your Config File to a Different Directory</h3>\n<p>Your WordPress config file contains information about things that are critical to your blog including access to your WordPress database. Though there are no known security issues with having your wp-config file in your root directory, WordPress 2.6 does allow you to move it to another directory.</p>\n<h3>Other Features</h3>\n<p>There are several other features to grab your attention and the few I talked about does not end the features you will get in the next major revision, here are some of the other things you should know about too;</p>\n<ul>\n<li>You can move your content directory from wp-content to any other place you want it to be. (This definitely will mean there are shorter links to your downloadable content or images)</li>\n<li>Better Theme Previewing.</li>\n<li>External JavaScript upgrades to TinyMCE, jQuery and jQuery UI.</li>\n<li>Customizable default avatars.</li>\n</ul>\n<p>Well hopefully this should be the best ever version yet of WordPress, though I still look forward to getting more. Let me know your views and opinions about the latest and probably greatest version of WordPress.</p>\n<p><em>Afterthought</em>: Aaron Brazell over at <a href="http://technosailor.com/2008/06/30/10-things-you-need-to-know-about-wordpress-26/">Technosailor goes into greater details on some of items on the WordPress 2.6 list of changes and updates</a>, including</p>\n<ul>\n<li>Shift Click selection of multiple checkboxes in the wp-admin</li>\n<li>More avatar options</li>\n<li>Page Templates of XML-RPC</li>\n<li>More &#8220;Press This&#8221; features</li>\n<li>Integrated Theme Preview</li>\n<li>Many other illustrated examples</li>\n</ul>";}i:44;a:7:{s:5:"title";s:41:"Matt: WordPress / Yahoo Brickhouse Meetup";s:4:"guid";s:20:"http://ma.tt/?p=6560";s:4:"link";s:55:"http://ma.tt/2008/06/wordpress-yahoo-brickhouse-meetup/";s:11:"description";s:276:"<p>If you&#8217;re in the San Francisco area <a href="http://upcoming.yahoo.com/event/854418">join us at the Yahoo! Brickhouse for a WordPress meetup this Wednesday</a>. This&#8217;ll actually be my first time at the Brickhouse, but I hear they have some mean Wii players.</p>";s:7:"pubdate";s:31:"Mon, 30 Jun 2008 19:01:21 +0000";s:2:"dc";a:1:{s:7:"creator";s:4:"Matt";}s:7:"summary";s:276:"<p>If you&#8217;re in the San Francisco area <a href="http://upcoming.yahoo.com/event/854418">join us at the Yahoo! Brickhouse for a WordPress meetup this Wednesday</a>. This&#8217;ll actually be my first time at the Brickhouse, but I hear they have some mean Wii players.</p>";}i:45;a:7:{s:5:"title";s:46:"Dougal Campbell: Update on WordPress blog APIs";s:4:"guid";s:32:"http://dougal.gunters.org/?p=991";s:4:"link";s:71:"http://dougal.gunters.org/blog/2008/06/30/update-on-wordpress-blog-apis";s:11:"description";s:2818:"<p><a href="http://dougal.gunters.org/blog/2008/06/24/wordpress-26-beta-1">I mentioned previously</a> that the <acronym title="eXtensible Markup Language"><span class="caps">XML</span></acronym>-<acronym title="Remote Procedure Call"><span class="caps">RPC</span></acronym> and Atom blog APIs would be disabled by default when <a href="http://wordpress.org/">WordPress</a> 2.6 is released. This was a matter of some debate within the community, and there has been some clarification:</p>\n<ul>\n<li>The APIs will <strong>not</strong> be automatically disabled for sites <em>upgrading</em> from older versions. Since the APIs have previously been &#8216;on&#8217; by default, they will continue to function.</li>\n<li><del datetime="2008-06-30T15:55:26+00:00">For <em>new installs</em> of WordPress 2.6 and later, there will be an option presented at install-time to enable the APIs.</del> <ins datetime="2008-06-30T15:55:26+00:00">Or not. They seem to have removed that between Beta 1 and Beta 2.</ins></li>\n<li>There will be options in the <code>Write</code> settings to enable or disable <acronym title="eXtensible Markup Language"><span class="caps">XML</span></acronym>-<acronym title="Remote Procedure Call"><span class="caps">RPC</span></acronym> posting and Atom <acronym title="Application Interface"><span class="caps">API</span></acronym> posting individually.</li>\n</ul>\n<p>This sounds like the most reasonable path to make this change without causing disruption for those who have been using client tools like <a href="http://infinite-sushi.com/software/ecto/">Ecto</a>, <a href="http://www.red-sweater.com/marsedit/">MarsEdit</a>, or <a href="http://windowslivewriter.spaces.live.com/">Windows Live Writer</a> (or third-party web services which can post to blogs, like <a href="http://flickr.com/">Flickr</a> or <a href="http://del.icio.us/">Delicious</a>) to post to their blogs.</p>\n<p>Also, though this change is being made under the moniker of a security improvement, that is not to imply that the current <acronym title="Application Interface"><span class="caps">API</span></acronym> code is not secure. It is simply a pretty standard practice to turn off services that are not used, just as when building a dedicated email server, you wouldn&#8217;t turn on FTP unless you absolutely needed it. <a href="http://wordpress.com/stats/posting/">Stats</a> from WordPress.com have shown that only about 5% of its users utilize the client APIs, so it doesn&#8217;t make sense to automatically turn it on for the 95% who <em>aren&#8217;t</em> using them.</p>\n<p><a href="http://sharethis.com/item?&wp=2.6&amp;publisher=06a70a77-1fc0-46a9-81d1-6a696e6ed23f&amp;title=Update+on+WordPress+blog+APIs&amp;url=http%3A%2F%2Fdougal.gunters.org%2Fblog%2F2008%2F06%2F30%2Fupdate-on-wordpress-blog-apis">ShareThis</a></p>";s:7:"pubdate";s:31:"Mon, 30 Jun 2008 13:45:35 +0000";s:2:"dc";a:1:{s:7:"creator";s:6:"Dougal";}s:7:"summary";s:2818:"<p><a href="http://dougal.gunters.org/blog/2008/06/24/wordpress-26-beta-1">I mentioned previously</a> that the <acronym title="eXtensible Markup Language"><span class="caps">XML</span></acronym>-<acronym title="Remote Procedure Call"><span class="caps">RPC</span></acronym> and Atom blog APIs would be disabled by default when <a href="http://wordpress.org/">WordPress</a> 2.6 is released. This was a matter of some debate within the community, and there has been some clarification:</p>\n<ul>\n<li>The APIs will <strong>not</strong> be automatically disabled for sites <em>upgrading</em> from older versions. Since the APIs have previously been &#8216;on&#8217; by default, they will continue to function.</li>\n<li><del datetime="2008-06-30T15:55:26+00:00">For <em>new installs</em> of WordPress 2.6 and later, there will be an option presented at install-time to enable the APIs.</del> <ins datetime="2008-06-30T15:55:26+00:00">Or not. They seem to have removed that between Beta 1 and Beta 2.</ins></li>\n<li>There will be options in the <code>Write</code> settings to enable or disable <acronym title="eXtensible Markup Language"><span class="caps">XML</span></acronym>-<acronym title="Remote Procedure Call"><span class="caps">RPC</span></acronym> posting and Atom <acronym title="Application Interface"><span class="caps">API</span></acronym> posting individually.</li>\n</ul>\n<p>This sounds like the most reasonable path to make this change without causing disruption for those who have been using client tools like <a href="http://infinite-sushi.com/software/ecto/">Ecto</a>, <a href="http://www.red-sweater.com/marsedit/">MarsEdit</a>, or <a href="http://windowslivewriter.spaces.live.com/">Windows Live Writer</a> (or third-party web services which can post to blogs, like <a href="http://flickr.com/">Flickr</a> or <a href="http://del.icio.us/">Delicious</a>) to post to their blogs.</p>\n<p>Also, though this change is being made under the moniker of a security improvement, that is not to imply that the current <acronym title="Application Interface"><span class="caps">API</span></acronym> code is not secure. It is simply a pretty standard practice to turn off services that are not used, just as when building a dedicated email server, you wouldn&#8217;t turn on FTP unless you absolutely needed it. <a href="http://wordpress.com/stats/posting/">Stats</a> from WordPress.com have shown that only about 5% of its users utilize the client APIs, so it doesn&#8217;t make sense to automatically turn it on for the 95% who <em>aren&#8217;t</em> using them.</p>\n<p><a href="http://sharethis.com/item?&wp=2.6&amp;publisher=06a70a77-1fc0-46a9-81d1-6a696e6ed23f&amp;title=Update+on+WordPress+blog+APIs&amp;url=http%3A%2F%2Fdougal.gunters.org%2Fblog%2F2008%2F06%2F30%2Fupdate-on-wordpress-blog-apis">ShareThis</a></p>";}i:46;a:7:{s:5:"title";s:59:"Weblog Tools Collection: WordPress Plugin Releases for 6/30";s:4:"guid";s:40:"http://weblogtoolscollection.com/?p=3697";s:4:"link";s:89:"http://weblogtoolscollection.com/archives/2008/06/30/wordpress-plugin-releases-for-630-2/";s:11:"description";s:2356:"<p><a href="http://www.asiden.dk/semi-manual-breadcrumb-navigation-plugin-for-wordpress/">Semi-manual Breadcrumb Navigation</a></p>\n<p>This plugin allows you to add breadcrumb navigation to your Wordpress installation. Unlike other Wordpress breadcrumb plugins, this one allows you to manually control the breadcrumb structure. At the same time it takes care of a few things automatically, hence the name.</p>\n<p><a href="http://ocaoimh.ie/exploit-scanner/">WordPress Exploit Scanner</a></p>\n<p>This plugin searches the files and database of your website for signs of suspicious activity. It will not stop someone hacking into your site, but it may help you find any uploaded or compromised files left by the hacker. When a website is compromised, hackers leave behind scripts and modified content that can be found by manually searching through all the files on a site. Some of the methods used to hide their code or spam links are obvious, like using CSS to hide text, and we can search for those strings.</p>\n<p><a href="http://wordpress.org/extend/plugins/drop-caps/">Drop Caps</a></p>\n<p>Adds mark-up to your posts and pages which allows you to create wicked drop cap.</p>\n<p><a href="http://adrien.gibrat.free.fr/wp-menus/">WP-Menus</a></p>\n<p>Allows to include user menus via sidebar widgets or in themes.</p>\n<p><a href="http://www.microkid.net/wordpress/related-posts/">Microkid&#8217;s Related Posts</a></p>\n<p>This Wordpress plugin lets you manually select related posts using a nifty AJAX powered search utility.</p>\n<p><a href="http://www.phpbits.info/wordpress-plugins/wp-related-post-plugin/">Related Posts WordPress Plugin</a></p>\n<p>The ‘Related Posts’ wordpress plug-in can be used to link other relevant posts with our own anchor text.</p>\n<p><a href="http://blog.collinsinternet.com/20/feed-subscriber-stats-wordpress-plugin/">Feed Subscriber Stats</a></p>\n<p>The plugin uses FeedBurner’s Awareness API to get your feed subscriber stats directly from FeedBurner.</p>\n<p><a href="http://broken-watch.info/?p=42">Inline Google Docs</a></p>\n<p>This plugin allows the user to embed Google Document/Spreadsheet content in posts and pages using shortcode.</p>\n<p><a href="http://www.sajithmr.com/wordpress-announcement-plugin/">WordPress Announcement</a></p>\n<p>Allows you to inform your visitors about any new updates to your site.</p>";s:7:"pubdate";s:31:"Mon, 30 Jun 2008 06:51:13 +0000";s:2:"dc";a:1:{s:7:"creator";s:4:"Ajay";}s:7:"summary";s:2356:"<p><a href="http://www.asiden.dk/semi-manual-breadcrumb-navigation-plugin-for-wordpress/">Semi-manual Breadcrumb Navigation</a></p>\n<p>This plugin allows you to add breadcrumb navigation to your Wordpress installation. Unlike other Wordpress breadcrumb plugins, this one allows you to manually control the breadcrumb structure. At the same time it takes care of a few things automatically, hence the name.</p>\n<p><a href="http://ocaoimh.ie/exploit-scanner/">WordPress Exploit Scanner</a></p>\n<p>This plugin searches the files and database of your website for signs of suspicious activity. It will not stop someone hacking into your site, but it may help you find any uploaded or compromised files left by the hacker. When a website is compromised, hackers leave behind scripts and modified content that can be found by manually searching through all the files on a site. Some of the methods used to hide their code or spam links are obvious, like using CSS to hide text, and we can search for those strings.</p>\n<p><a href="http://wordpress.org/extend/plugins/drop-caps/">Drop Caps</a></p>\n<p>Adds mark-up to your posts and pages which allows you to create wicked drop cap.</p>\n<p><a href="http://adrien.gibrat.free.fr/wp-menus/">WP-Menus</a></p>\n<p>Allows to include user menus via sidebar widgets or in themes.</p>\n<p><a href="http://www.microkid.net/wordpress/related-posts/">Microkid&#8217;s Related Posts</a></p>\n<p>This Wordpress plugin lets you manually select related posts using a nifty AJAX powered search utility.</p>\n<p><a href="http://www.phpbits.info/wordpress-plugins/wp-related-post-plugin/">Related Posts WordPress Plugin</a></p>\n<p>The ‘Related Posts’ wordpress plug-in can be used to link other relevant posts with our own anchor text.</p>\n<p><a href="http://blog.collinsinternet.com/20/feed-subscriber-stats-wordpress-plugin/">Feed Subscriber Stats</a></p>\n<p>The plugin uses FeedBurner’s Awareness API to get your feed subscriber stats directly from FeedBurner.</p>\n<p><a href="http://broken-watch.info/?p=42">Inline Google Docs</a></p>\n<p>This plugin allows the user to embed Google Document/Spreadsheet content in posts and pages using shortcode.</p>\n<p><a href="http://www.sajithmr.com/wordpress-announcement-plugin/">WordPress Announcement</a></p>\n<p>Allows you to inform your visitors about any new updates to your site.</p>";}i:47;a:7:{s:5:"title";s:46:"Weblog Tools Collection: 3 Under Rated Plugins";s:4:"guid";s:40:"http://weblogtoolscollection.com/?p=3695";s:4:"link";s:75:"http://weblogtoolscollection.com/archives/2008/06/29/3-under-rated-plugins/";s:11:"description";s:2520:"<p>There appears to be a WordPress meme going around (started by <a href="http://wordpress.jdwebdev.com/blog/underrated-wordpress-plugins/" target="_blank">John at WordPress Expert</a>) where members throughout the community are tagging other blogs along with mentioning three plugins which they feel are under rated. Although I don&#8217;t have access to the plugins used here on WLTC, I would like to bring about three under rated plugins I use on my own blog.</p>\n<ol>\n<li><a href="http://www.aviransplace.com/index.php/digg-this-wordpress-plugin/" target="_blank">DiggThis</a> - This plugin was written by <cite><a title="Visit author homepage" href="http://www.aviransplace.com/">Aviran Mordod</a></cite> This by far my favorite DiggThis plugin because it only displays on posts which have been submitted to Digg. My opinion, which is shared by many others is that, it&#8217;s better to show a DiggThis button when the article has been submitted to Digg rather than showing a Digg button next to every article. Unless you are ReadWriteWeb or some other mainstream blog, those buttons will show 0 diggs and will possibly hint to the content not being up to snuff. I suppose its one of those psychological things.</li>\n<li><a href="http://rmarsh.com/plugins/highlight-comments/" target="_blank">Highlight Author Comments</a> - This plugin written by <cite><a title="Visit author homepage" href="http://rmarsh.com/">Rob Marsh, SJ</a>.</cite> makes following comments written by the blog author a cinch. After installing and then activating the plugin, you can style what blog authors comments will look like, giving you the ability to distinguish your comments versus all other comments.</li>\n<li><a href="http://blogwaffe.com/2006/10/04/421/" target="_blank">No Self Pings</a> - No one has been able to tell me what the purpose is behind WordPress sending pings and tackbacks to itself if you link to an article located in your archive. I&#8217;ve found myself always deleting these pingbacks. Thanks this this plugin written by <cite><a title="Visit author homepage" href="http://blogwaffe.com/">Michael D. Adams</a>.</cite> this is no longer an issue for me. Now, I can easily link to myself without having to deal with those pingbacks giving me that much more free time to do other things.</li>\n</ol>\n<p>These are three plugins which I feel are under rated that I use on my own blog. I invite you to partake in this meme and highlight three plugins you are using on your own blog that you feel are under rated.</p>";s:7:"pubdate";s:31:"Sun, 29 Jun 2008 22:44:53 +0000";s:2:"dc";a:1:{s:7:"creator";s:13:"Jeff Chandler";}s:7:"summary";s:2520:"<p>There appears to be a WordPress meme going around (started by <a href="http://wordpress.jdwebdev.com/blog/underrated-wordpress-plugins/" target="_blank">John at WordPress Expert</a>) where members throughout the community are tagging other blogs along with mentioning three plugins which they feel are under rated. Although I don&#8217;t have access to the plugins used here on WLTC, I would like to bring about three under rated plugins I use on my own blog.</p>\n<ol>\n<li><a href="http://www.aviransplace.com/index.php/digg-this-wordpress-plugin/" target="_blank">DiggThis</a> - This plugin was written by <cite><a title="Visit author homepage" href="http://www.aviransplace.com/">Aviran Mordod</a></cite> This by far my favorite DiggThis plugin because it only displays on posts which have been submitted to Digg. My opinion, which is shared by many others is that, it&#8217;s better to show a DiggThis button when the article has been submitted to Digg rather than showing a Digg button next to every article. Unless you are ReadWriteWeb or some other mainstream blog, those buttons will show 0 diggs and will possibly hint to the content not being up to snuff. I suppose its one of those psychological things.</li>\n<li><a href="http://rmarsh.com/plugins/highlight-comments/" target="_blank">Highlight Author Comments</a> - This plugin written by <cite><a title="Visit author homepage" href="http://rmarsh.com/">Rob Marsh, SJ</a>.</cite> makes following comments written by the blog author a cinch. After installing and then activating the plugin, you can style what blog authors comments will look like, giving you the ability to distinguish your comments versus all other comments.</li>\n<li><a href="http://blogwaffe.com/2006/10/04/421/" target="_blank">No Self Pings</a> - No one has been able to tell me what the purpose is behind WordPress sending pings and tackbacks to itself if you link to an article located in your archive. I&#8217;ve found myself always deleting these pingbacks. Thanks this this plugin written by <cite><a title="Visit author homepage" href="http://blogwaffe.com/">Michael D. Adams</a>.</cite> this is no longer an issue for me. Now, I can easily link to myself without having to deal with those pingbacks giving me that much more free time to do other things.</li>\n</ol>\n<p>These are three plugins which I feel are under rated that I use on my own blog. I invite you to partake in this meme and highlight three plugins you are using on your own blog that you feel are under rated.</p>";}i:48;a:7:{s:5:"title";s:51:"Weblog Tools Collection: Google Trends for Websites";s:4:"guid";s:40:"http://weblogtoolscollection.com/?p=3694";s:4:"link";s:80:"http://weblogtoolscollection.com/archives/2008/06/28/google-trends-for-websites/";s:11:"description";s:635:"<p><a href="http://trends.google.com/websites?q=weblogtoolscollection.com">Google Trends: weblogtoolscollection.com</a> provides (slightly) interesting facts on your blog. Though the product is free, signing in is required to see the number estimates. Not all sites seem to have a lot of data in Google Trends but it was fun to browse the various links. Most interesting to me were the &#8220;also visited&#8221; section and the &#8220;also searched&#8221; section. <a href="http://www.mattcutts.com/blog/google-trends-for-websites/">Matt Cutts had an interesting writeup on Google Trends for websites</a> a little over a week ago.</p>";s:7:"pubdate";s:31:"Sat, 28 Jun 2008 23:57:02 +0000";s:2:"dc";a:1:{s:7:"creator";s:10:"Mark Ghosh";}s:7:"summary";s:635:"<p><a href="http://trends.google.com/websites?q=weblogtoolscollection.com">Google Trends: weblogtoolscollection.com</a> provides (slightly) interesting facts on your blog. Though the product is free, signing in is required to see the number estimates. Not all sites seem to have a lot of data in Google Trends but it was fun to browse the various links. Most interesting to me were the &#8220;also visited&#8221; section and the &#8220;also searched&#8221; section. <a href="http://www.mattcutts.com/blog/google-trends-for-websites/">Matt Cutts had an interesting writeup on Google Trends for websites</a> a little over a week ago.</p>";}i:49;a:7:{s:5:"title";s:26:"Alex King: PhoneFactor 1.0";s:4:"guid";s:50:"http://alexking.org/blog/2008/06/27/phonefactor-10";s:4:"link";s:50:"http://alexking.org/blog/2008/06/27/phonefactor-10";s:11:"description";s:3322:"<p>PhoneFactor is a <a href="http://wordpress.org/" rel="external">WordPress</a> plugin that provides an additional layer of security when logging in to your WordPress site.</p>\n<p class="center"><a href="http://www.flickr.com/photos/alexkingorg/sets/72157605848461623/"><img src="http://farm4.static.flickr.com/3149/2616262594_5cf244979b_m.jpg" width="240" height="177" alt="Login" /></a></p>\n<p>It&#8217;s a pretty cool system. When you log in to your WordPress blog with PhoneFactor enabled, you receive a phone call asking you to press # to authorize. When you do so, you are logged in. If you do not, then the login attempt fails.</p>\n<p>Basically, this means someone needs to get your username, password <em>and</em> phone in order to log in to your WordPress site as you.</p>\n<p><a href="http://crowdfavorite.com">Crowd Favorite</a> worked with the <a href="http://phonefactor.com/" rel="external">PhoneFactor</a> team to build this integration on their API layer. This was a fun project for us - it&#8217;s always nice to enhance WordPress by integrating features from another service.</p>\n<p>Besides building the integration with the API to authenticate via phone, we also built the PhoneFactor registration step right into the WordPress admin so that the user wouldn&#8217;t have to leave the WordPress admin when activating the plugin and getting it set up. I think it&#8217;s a much better user experience.</p>\n<p class="center"><a href="http://www.flickr.com/photos/alexkingorg/2615434383/" title="Registration by alexkingorg, on Flickr"><img src="http://farm4.static.flickr.com/3119/2615434383_9647b143f0_m.jpg" width="240" height="178" alt="Registration" /></a></p>\n<p>We integrated some instructional banners into the WordPress admin pages to let people know the next steps to getting things set up after activating the plugin. We also built in some more advanced user features like whitelisting IP addresses so that you don&#8217;t have to use PhoneFactor authentication if you&#8217;re logging in from your home machine.</p>\n<p>The download and more information are available at the <a href="http://wordpress.org/extend/plugins/phonefactor/">WordPress Plugin repository</a> on wordpress.org.</p>\n<p>Enjoy!</p>\n<p><a href="http://sharethis.com/item?&wp=2.2.3&amp;publisher=06654962-d77d-102a-861d-00161729a8a2&amp;title=PhoneFactor+1.0&amp;url=http%3A%2F%2Falexking.org%2Fblog%2F2008%2F06%2F27%2Fphonefactor-10">ShareThis</a></p>\n	<!--\n	<rdf:RDF xmlns="http://web.resource.org/cc/" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">\n	<Work rdf:about="">\n		<license rdf:resource="http://creativecommons.org/licenses/by-nc-sa/2.5/" />\n	<dc:type rdf:resource="http://purl.org/dc/dcmitype/Text" />\n	</Work>\n	<License rdf:about="http://creativecommons.org/licenses/by-nc-sa/2.5/"><permits rdf:resource="http://web.resource.org/cc/Reproduction"/><permits rdf:resource="http://web.resource.org/cc/Distribution"/><requires rdf:resource="http://web.resource.org/cc/Notice"/><requires rdf:resource="http://web.resource.org/cc/Attribution"/><prohibits rdf:resource="http://web.resource.org/cc/CommercialUse"/><permits rdf:resource="http://web.resource.org/cc/DerivativeWorks"/><requires rdf:resource="http://web.resource.org/cc/ShareAlike"/></License></rdf:RDF>\n	-->";s:7:"pubdate";s:31:"Fri, 27 Jun 2008 23:13:22 +0000";s:2:"dc";a:1:{s:7:"creator";s:4:"Alex";}s:7:"summary";s:3322:"<p>PhoneFactor is a <a href="http://wordpress.org/" rel="external">WordPress</a> plugin that provides an additional layer of security when logging in to your WordPress site.</p>\n<p class="center"><a href="http://www.flickr.com/photos/alexkingorg/sets/72157605848461623/"><img src="http://farm4.static.flickr.com/3149/2616262594_5cf244979b_m.jpg" width="240" height="177" alt="Login" /></a></p>\n<p>It&#8217;s a pretty cool system. When you log in to your WordPress blog with PhoneFactor enabled, you receive a phone call asking you to press # to authorize. When you do so, you are logged in. If you do not, then the login attempt fails.</p>\n<p>Basically, this means someone needs to get your username, password <em>and</em> phone in order to log in to your WordPress site as you.</p>\n<p><a href="http://crowdfavorite.com">Crowd Favorite</a> worked with the <a href="http://phonefactor.com/" rel="external">PhoneFactor</a> team to build this integration on their API layer. This was a fun project for us - it&#8217;s always nice to enhance WordPress by integrating features from another service.</p>\n<p>Besides building the integration with the API to authenticate via phone, we also built the PhoneFactor registration step right into the WordPress admin so that the user wouldn&#8217;t have to leave the WordPress admin when activating the plugin and getting it set up. I think it&#8217;s a much better user experience.</p>\n<p class="center"><a href="http://www.flickr.com/photos/alexkingorg/2615434383/" title="Registration by alexkingorg, on Flickr"><img src="http://farm4.static.flickr.com/3119/2615434383_9647b143f0_m.jpg" width="240" height="178" alt="Registration" /></a></p>\n<p>We integrated some instructional banners into the WordPress admin pages to let people know the next steps to getting things set up after activating the plugin. We also built in some more advanced user features like whitelisting IP addresses so that you don&#8217;t have to use PhoneFactor authentication if you&#8217;re logging in from your home machine.</p>\n<p>The download and more information are available at the <a href="http://wordpress.org/extend/plugins/phonefactor/">WordPress Plugin repository</a> on wordpress.org.</p>\n<p>Enjoy!</p>\n<p><a href="http://sharethis.com/item?&wp=2.2.3&amp;publisher=06654962-d77d-102a-861d-00161729a8a2&amp;title=PhoneFactor+1.0&amp;url=http%3A%2F%2Falexking.org%2Fblog%2F2008%2F06%2F27%2Fphonefactor-10">ShareThis</a></p>\n	<!--\n	<rdf:RDF xmlns="http://web.resource.org/cc/" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:rdf="http://www.w3.org/1999/02/22-rdf-syntax-ns#">\n	<Work rdf:about="">\n		<license rdf:resource="http://creativecommons.org/licenses/by-nc-sa/2.5/" />\n	<dc:type rdf:resource="http://purl.org/dc/dcmitype/Text" />\n	</Work>\n	<License rdf:about="http://creativecommons.org/licenses/by-nc-sa/2.5/"><permits rdf:resource="http://web.resource.org/cc/Reproduction"/><permits rdf:resource="http://web.resource.org/cc/Distribution"/><requires rdf:resource="http://web.resource.org/cc/Notice"/><requires rdf:resource="http://web.resource.org/cc/Attribution"/><prohibits rdf:resource="http://web.resource.org/cc/CommercialUse"/><permits rdf:resource="http://web.resource.org/cc/DerivativeWorks"/><requires rdf:resource="http://web.resource.org/cc/ShareAlike"/></License></rdf:RDF>\n	-->";}}s:7:"channel";a:5:{s:5:"title";s:16:"WordPress Planet";s:4:"link";s:28:"http://planet.wordpress.org/";s:8:"language";s:2:"en";s:11:"description";s:47:"WordPress Planet - http://planet.wordpress.org/";s:7:"tagline";s:47:"WordPress Planet - http://planet.wordpress.org/";}s:9:"textinput";a:0:{}s:5:"image";a:0:{}s:9:"feed_type";s:3:"RSS";s:12:"feed_version";s:3:"2.0";s:5:"stack";a:0:{}s:9:"inchannel";b:0;s:6:"initem";b:0;s:9:"incontent";b:0;s:11:"intextinput";b:0;s:7:"inimage";b:0;s:13:"current_field";s:0:"";s:17:"current_namespace";b:0;s:19:"_CONTENT_CONSTRUCTS";a:6:{i:0;s:7:"content";i:1;s:7:"summary";i:2;s:4:"info";i:3;s:5:"title";i:4;s:7:"tagline";i:5;s:9:"copyright";}s:4:"etag";s:25:""2a1cb-487d1deb-c10597"\r\n";s:13:"last_modified";s:31:"Tue, 15 Jul 2008 22:00:11 GMT\r\n";}', 'no');
