(166, 1, '2007-05-11 15:12:37', '2007-05-11 20:12:37', '', 'off_road_step09.jpg', 0, '', 'inherit', 'open', 'open', '', 'off_road_step09jpg', '', '', '2007-05-11 15:12:37', '2007-05-11 20:12:37', '', -1178913994, 'http://bitpimps.lixlink.com/articles/wp-content/uploads/2007/05/off_road_step09.jpg', 0, 'attachment', 'image/jpeg', 0),
